<?php
require_once __DIR__.'/includes/functions.php';
$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM cars WHERE id=?');$s->execute([$id]);$car=$s->fetch();if(!$car){http_response_code(404);$pageTitle='Car not found';require __DIR__.'/includes/header.php';echo '<section class="section container"><h1>Car not found</h1><a href="'.e(url('cars.php')).'">Back to cars</a></section>';require __DIR__.'/includes/footer.php';exit;}
$pageTitle=$car['name'].' — DriveEase';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();require_login();$pickup=$_POST['pickup_date']??'';$ret=$_POST['return_date']??'';$location=trim($_POST['pickup_location']??'');$driver=isset($_POST['driver_required'])?1:0;
if(!$pickup||!$ret||$pickup<date('Y-m-d')||$ret<=$pickup)$errors[]='Choose a valid pickup date and a return date after pickup.';
if($location==='')$errors[]='Pickup location is required.';
if($car['status']!=='available')$errors[]='This car is not currently available.';
if(!$errors){$check=db()->prepare("SELECT COUNT(*) FROM reservations WHERE car_id=? AND status IN ('pending','confirmed','active') AND pickup_date < ? AND return_date > ?");$check->execute([$id,$ret,$pickup]);if((int)$check->fetchColumn()>0)$errors[]='This car already has a reservation overlapping those dates.';}
if(!$errors){$days=(new DateTime($pickup))->diff(new DateTime($ret))->days;$total=$days*(float)$car['rate_per_day'];$ins=db()->prepare("INSERT INTO reservations (customer_id,car_id,pickup_date,return_date,pickup_location,driver_required,days,total_amount,status) VALUES (?,?,?,?,?,?,?,?, 'pending')");$ins->execute([current_user()['id'],$id,$pickup,$ret,$location,$driver,$days,$total]);$rid=(int)db()->lastInsertId();log_activity('Created reservation #'.$rid);flash('success','Reservation request submitted. Track its status from your dashboard.');redirect('dashboard.php');}}
require __DIR__.'/includes/header.php'; ?>
<section class="section"><div class="container detail-grid"><div><a class="back-link" href="<?= e(url('cars.php')) ?>">← Back to fleet</a><div class="detail-photo"><?php if($car['image_url']): ?><img src="<?= e($car['image_url']) ?>" alt="<?= e($car['name']) ?>"><?php else: ?><div class="car-placeholder">🚘</div><?php endif; ?></div><div class="detail-info"><span class="eyebrow">VEHICLE DETAILS</span><h1><?= e($car['name']) ?></h1><p><?= e($car['description'] ?: 'A reliable option for your next trip. Contact our team if you need help planning your rental.') ?></p><div class="detail-spec-grid"><div><small>Model</small><b><?= e($car['model']) ?></b></div><div><small>Color</small><b><?= e($car['color']) ?></b></div><div><small>Transmission</small><b><?= e($car['transmission']) ?></b></div><div><small>Seats</small><b><?= (int)$car['seats'] ?> passengers</b></div><div><small>Registration</small><b><?= e($car['registration_no']) ?></b></div><div><small>Status</small><b><?= e(ucfirst($car['status'])) ?></b></div></div></div></div><aside class="booking-panel"><div class="booking-price"><?= money($car['rate_per_day']) ?><small> / day</small></div><h2>Reserve this car</h2><p>Send a reservation request. Staff will review and confirm availability.</p><?php if($errors): ?><div class="alert alert-danger"><ul><?php foreach($errors as $er): ?><li><?= e($er) ?></li><?php endforeach; ?></ul></div><?php endif; ?><?php if($car['status']!=='available'): ?><div class="alert alert-warning">This vehicle is not currently available.</div><?php elseif(!logged_in()): ?><a class="btn btn-primary btn-block" href="<?= e(url('login.php')) ?>">Sign in to reserve</a><?php else: ?><form method="post" class="form-stack"><?= csrf_field() ?><label>Pickup date<input required type="date" name="pickup_date" min="<?= date('Y-m-d') ?>" value="<?= e($_POST['pickup_date']??'') ?>"></label><label>Return date<input required type="date" name="return_date" min="<?= date('Y-m-d',strtotime('+1 day')) ?>" value="<?= e($_POST['return_date']??'') ?>"></label><label>Pickup location<input required name="pickup_location" placeholder="e.g. Lahore city centre" value="<?= e($_POST['pickup_location']??'') ?>"></label><label class="checkbox-line"><input type="checkbox" name="driver_required" <?= isset($_POST['driver_required'])?'checked':'' ?>> I need a driver</label><button class="btn btn-primary btn-block" type="submit">Request reservation ↗</button><small class="muted">This is a request, not a confirmed booking. Final status is set by staff.</small></form><?php endif; ?><div class="booking-assurance"><span>✓</span><p><b>Transparent pricing</b><br><small>Total is calculated by rental days × daily rate.</small></p></div></aside></div></section>
